  padding: 80px 0;
  background: #f6f2ea;
  min-height: 70vh;
}

.proposal-shell {
  max-width: 1120px;
  margin: 0 auto;
}

.section-head {
  margin-bottom: 28px;
  max-width: 780px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.78rem;
  color: #b58b4a;
  font-weight: 700;
}

h1 {
  color: #08263a;
  margin: 8px 0;
}

.section-head p,
.muted {
  color: #516070;
  line-height: 1.6;
}

.proposal-tabs {
  display: inline-flex;
  gap: 0.5rem;
  background: rgba(8, 38, 58, 0.06);
  border-radius: 999px;
  padding: 0.35rem;
  margin: 1rem 0;
}

.proposal-tabs button {
  border: 0;
  border-radius: 999px;
  background: transparent;
  padding: 0.7rem 1.1rem;
  color: #08263a;
  font-weight: 800;
  cursor: pointer;
}

.proposal-tabs button.active {
  background: #fff;
  box-shadow: 0 8px 22px rgba(8, 38, 58, 0.08);
}

.proposal-tabs span {
  display: inline-flex;
  min-width: 1.6rem;
  height: 1.6rem;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: rgba(181, 139, 74, 0.16);
  color: #b58b4a;
  margin-left: 0.35rem;
}

.proposal-toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.85rem;
  align-items: end;
  margin: 1rem 0 1.4rem;
}

.proposal-toolbar label {
  display: grid;
  gap: 0.35rem;
  color: #08263a;
  font-weight: 700;
  min-width: 260px;
}

.proposal-toolbar input {
  min-height: 42px;
  border: 1px solid rgba(8, 38, 58, 0.16);
  border-radius: 14px;
  padding: 0.65rem 0.75rem;
  background: #fff;
  font: inherit;
}

.proposal-list {
  display: grid;
  gap: 1rem;
}

.proposal-card,
.empty-card {
  background: #fff;
  border-radius: 24px;
  padding: 1.25rem;
  border: 1px solid rgba(8, 38, 58, 0.08);
  box-shadow: 0 18px 45px rgba(8, 38, 58, 0.08);
}

.proposal-card {
  cursor: pointer;
}

.proposal-card:hover {
  transform: translateY(-1px);
  box-shadow: 0 22px 55px rgba(8, 38, 58, 0.12);
}

.proposal-top {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.75rem;
  align-items: center;
}

.status-pill {
  display: inline-flex;
  border-radius: 999px;
  background: rgba(181, 139, 74, 0.12);
  color: #8a652d;
  padding: 6px 10px;
  font-size: 0.78rem;
  font-weight: 800;
}

.status-accepted {
  background: rgba(4, 120, 87, 0.12);
  color: #047857;
}

.status-declined,
.status-expired {
  background: rgba(185, 28, 28, 0.1);
  color: #b91c1c;
}

.validity {
  color: #516070;
  font-size: 0.9rem;
}

.proposal-card h2 {
  margin: 1rem 0 0.35rem;
  color: #08263a;
}

.proposal-date,
.proposal-message {
  color: #516070;
  line-height: 1.5;
}

.proposal-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 0.75rem;
  margin: 1rem 0;
}

.proposal-grid div {
  display: grid;
  gap: 0.25rem;
  background: #f8f5ef;
  border-radius: 16px;
  padding: 0.9rem;
}

.proposal-grid strong {
  color: #08263a;
}

.proposal-grid span {
  color: #516070;
  font-weight: 700;
}

.proposal-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1rem;
}

.btn {
  border: 0;
  border-radius: 999px;
  padding: 0.7rem 1rem;
  font-weight: 800;
  cursor: pointer;
  text-decoration: none;
}

.btn-primary {
  background: #08263a;
  color: #fff;
}

.btn-secondary {
  background: #efe7da;
  color: #08263a;
}

.error-message {
  color: #b91c1c;
}

@media (max-width: 640px) {
  .proposal-tabs {
    width: 100%;
    overflow: auto;
  }
  .proposal-toolbar label {
    min-width: 100%;
  }
